+test('CLI success, errors, and import without CLI side effects',()=>{
+  const directory=mkdtempSync(join(tmpdir(),'patch-transaction-'));
+  try{
+    const fixture=join(directory,'input.json');
+    writeFileSync(fixture,JSON.stringify({source:'😀\r\n',edits:[edit(0,2,'😀','ok')],extra:1}));
+    const success=run([fixture]);
+    assert.equal(success.status,0);
+    assert.equal(success.stderr,'');
+    assert.equal(success.stdout,JSON.stringify({text:'ok\r\n',applied:1})+'\n');
+    const expectFailure=(args)=>{
+      const result=run(args);
+      assert.equal(result.status,2);
+      assert.equal(result.stdout,'');
+      assert.ok(result.stderr.trim());
+    };
+    expectFailure([]);
+    expectFailure([fixture,'extra']);
+    expectFailure([join(directory,'missing.json')]);
+    for(const contents of ['{','null','[]','{}',JSON.stringify({source:'a',edits:[edit(0,1,'wrong')]}),
+      JSON.stringify({source:'a',edits:[edit(0,1,'a'),edit(1,1,'','!')]})]){
+      writeFileSync(fixture,contents);
+      expectFailure([fixture]);
+    }
+    const imported=spawnSync(process.execPath,['--input-type=module','-e',
+      `await import(${JSON.stringify(moduleURL.href)})`],{encoding:'utf8'});
+    assert.equal(imported.status,0);
+    assert.equal(imported.stdout,'');
+    assert.equal(imported.stderr,'');
+  }finally{
+    rmSync(directory,{recursive:true,force:true});
+  }
+});
